import json,hashlib
from pathlib import Path
root=Path('FOREVER_WORKS/PHASE26');root.mkdir(exist_ok=True)
ext={'authority':'Owner Phase 2.6 assignment plus mandatory adapter-only addendum in docs/phase26; observed implementation is partial, not accepted intent or certification.','promoted':False,'limitations':'docs/phase26/IMPLEMENTATION.md'}
records={g:[] for g in ['capabilities','invariants','compatibility','implementations','evidence']}
def write(group,name,obj):
 (root/name).write_text(json.dumps({'foreverVersion':'0.1',**obj,'extensions':{'org.redown':ext}},indent=2)+'\n');records[group].append(name)
write('invariants','portability.json',{'id':'redown.p26.invariant.portability','kind':'invariant','name':'Adapter-only provider evolution','statement':'New providers implement and register primitives, identity semantics and declarative capabilities. Preserve one canonical coordinator, authorized session intersection, source preservation, independent integrity evidence, job identity, Atlas instrumentation and SDK/UI compatibility. Unsupported operations remain explicit.','severity':'critical'})
write('capabilities','universal.json',{'id':'redown.p26.capability.universal','kind':'capability','name':'Universal provider contracts and external client','statement':'Expose versioned filesystem operations through the same authorized bridge and coordinator for path and native-ID adapters.','status':'partial','criticality':'essential','relatedInvariants':['redown.p26.invariant.portability'],'relatedImplementations':['redown.p26.implementation.foundation']})
write('compatibility','versions.json',{'id':'redown.p26.compatibility.versions','kind':'compatibility','contractType':'API','boundary':'0.1 simulation facade, 0.2 exact-key callers, additive 0.3 locator callers, provider contract 1.0.0','version':'1.0','mustPreserve':['Existing callers and production Explorer isolation','No automatic ambiguous write retry or unsafe deletion','No provider-specific Python authentication or transfers','Explicit provider differences and unsupported operations'],'migrationPolicy':'Additive optional fields/capabilities within a contract major; preserve old request schemas. Incompatible required semantics require a new version with compatibility tests and purpose-preserving migration.','validationReferences':['redown.p26.evidence.foundation']})
paths=['extension/file-engine/engine.mjs','extension/file-engine/provider-contract.mjs','extension/file-engine/universal-operations.mjs','extension/file-engine/providers.json','agent/files/api.mjs','agent/files/bootstrap.mjs','clients/python/redown/client.py','extension/beta-explorer.mjs','agent/aac/model.mjs']
refs=[{'path':p,'sha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()} for p in paths]
write('implementations','foundation.json',{'id':'redown.p26.implementation.foundation','kind':'implementation','type':'library','technology':'Canonical ES module coordinator, versioned JSON Schema, Python stdio SDK','version':'0.3.0','satisfiesCapabilities':['redown.p26.capability.universal'],'constrainedByInvariants':['redown.p26.invariant.portability'],'compatibilityContracts':['redown.p26.compatibility.versions'],'sourceLocations':paths,'replaceability':'Preserve locator ownership, version negotiation, capability limits, engine/session scope intersection, conditional deletion refusal, job receipts, independent byte verification and bounded diagnostic outputs.'})
p=root/'foundation.json';s=json.loads(p.read_text());s['extensions']['org.redown']={**ext,'sourceRefs':refs,'historicalBindings':'Existing P2-R2-API source bindings are retained unchanged; their freshness check fails after this intentional migration. This supplement does not erase that failure.'};p.write_text(json.dumps(s,indent=2)+'\n')
write('evidence','foundation-evidence.json',{'id':'redown.p26.evidence.foundation','kind':'evidence','type':'integration-test','source':'verification/phase26/provider-evidence.json','statementSupported':'Three credential-free/reference providers completed a deterministic session copy with separate persisted-byte or filesystem verification and operation-correlated Atlas evidence. Python and R2 evidence are separately scoped.','confidence':1,'immutableReference':'sha256:'+hashlib.sha256(Path('verification/phase26/provider-evidence.json').read_bytes()).hexdigest()})
(root/'manifest.json').write_text(json.dumps({'foreverVersion':'0.1','projectId':'redown-phase26-universal-foundation','records':records,'extensions':{'org.redown':ext}},indent=2)+'\n')
